[5531]={"Betina Bigozinco","Leve os Ovos Congelados para Betina Bigozinco."},
[5534]={"Equipamento \"Sumido\" de Kam'arawn","Encontre Essa Tal Runa que está com as nagas nas Ruínas de Eldarath e traga-a para Kam'arawn, em Azshara."},
[5535]={"Perturbação espiritual","Destrua 6 Aparições Altaneiras e 6 Subliches Altaneiros. Depois, fale com Loh'atu em Azshara."},
[5536]={"Uma terra repleta de ódio","Mate 6 Sátiros Haldarr, 2 Trapaceiros Haldarr e 2 Devotos Vil Haldarr. Depois, fale novamente com Loh'atu na fronteira do Vale Gris."},
[5542]={"Cães demoníacos","Mate 20 Cães Pestilentos Miúdos, 5 Cães Pestilentos e 5 Cães Pestilentos Frenéticos. Fale novamente com Tirion Fordring quando a tarefa estiver concluída."},
[5543]={"Céu tingido de sangue","Mate 30 Quirópragos e fale novamente com Tirion Fordring."},
[5544]={"Carne de verme carniceiro","Procure os Vermes Carniceiros e os Devoradores de Carniça da região. Mate-os e tire a carne. Fale novamente com Tirion Fordring depois que tiver juntado 15 Nacos de Carne de Verme Carniceiro."},
[5561]={"Arrebanhamento de kodos","Leve cinco Kodos Domados e o Kodoagrupandador para Smid Rabiscafuso no Acampamento do Rabiscafuso."},
[5581]={"Portais para a Legião","Feche 6 portais nas Ruínas de Mannoroc e fale com Taiga Crina Sábia na Aldeia Pescassombra."},
[5582]={"Escama de dragão saudável","Leve a Escama de Dragão Saudável para Betina Bigozinco na Capela Esperança da Luz, que fica nas Terras Pestilentas Orientais."},
