[5730]={"Inimigos ocultos","Fale com Thrall em Orgrimmar e conte a ele o que você descobriu."},
[5741]={"O Cetro de Luz","Pegue o Cetro de Luz e devolva-o para Azore Albamorte na torre de Ethel Rethor."},
[5742]={"Redenção","Escute o que Tirion Fordring tem a dizer."},
[5761]={"Mate a besta","Entre nas Cavernas Ígneas e mate Taragaman, o Famélico, depois leve o coração dele para Neeru Cortafogo em Orgrimmar."},
[5762]={"Rosarães Guima","Leve o Caixote de Kravel para Rosarães Guima na Selva do Espinhaço."},
[5763]={"Caçada na Selva do Espinhaço","Leve o Chifre de Kodo de Roon para Rosarães Guima na Selva do Espinhaço."},
[5781]={"Elixir de memórias esquecidas","Viaje para a Chácara Secreta, no extremo sul das Terras Pestilentas Orientais, e recupere o Martelo de Taelan. Fale novamente com Tirion Fordring ao completar seu objetivo."},
[5802]={"A forja do Pico Penacho de Fogo","Leve o Molde de Chave-mestra e 2 Barras de Tório para o topo do Pico Penacho de Fogo, na Cratera Un'Goro. Use o Molde de Chave-mestra no lago de lava para forjar a Chave-mestra Inacabada."},
[5804]={"O escaravelho de Araj","Destrua Araj, o Evocador e leve o Escaravelho de Araj para o Boticário Trépido no Baluarte, que fica nas Terras Pestilentas Ocidentais."},
[5821]={"Procura-se guarda-costas","Escolte a Caravana Gizelton pela aldeia dos Centauros Kolkar. Fale com o Smid no Acampamento do Rabiscafuso para receber a recompensa."},
[5845]={"Da honra perdida","Viaje para o Vilarejo do Norte, na região nordeste das Terras Pestilentas Orientais, e recupere o Símbolo da Honra Perdida. Fale novamente com Tirion Fordring ao completar seu objetivo."},
[5846]={"Do amor e da família","Viaje para a ilha de Castro das Flechas, na região centro-sul das Terras Pestilentas, e procure pistas sobre o paradeiro da pintura."},
[5848]={"Do amor e da família","Viaje para Stratholme, na parte norte das Terras Pestilentas. No Bastião Escarlate, você encontrará a pintura \"Do Amor e da Família\", escondida atrás de outro quadro que retrata as luas gêmeas do nosso mundo."},
[5861]={"Encontrando Myranda","Viaje para a Tumba de Uther, que fica nas Terras Pestilentas meridionais. Mostre a Dádiva de Tirion para Myranda, a Bruxa Velha."},
[5862]={"Subterfúgio Escarlate","Fale com Myranda para receber a Ilusão Escarlate. Viaje para Amparo sob o efeito de Ilusão Escarlate e entregue a Dádiva de Tirion para o Grão-lorde Taelan Fordring."},
[5863]={"O Complexo Dunamalho","Andi Lynn em Geringontzan quer que você destrua o Complexo Dunamalho. Para isso, deve matar 10 Brutamontes Dunamalho, 10 Impositores Dunamalho e Gor'marok, o Assolador."},
[5881]={"Chamando as reservas","Maggran quer que você entregue uma carta a Grish Pisaléguas no Grande Elevador, que fica nos Sertões."},
[5887]={"Bálsamo via caça"},
[5888]={"Bálsamo via mineração"},
[5889]={"Bálsamo via coleta"},
[5890]={"Bálsamo via esfolamento"},
[5891]={"Bálsamo via desencantamento"},
[5893]={"Suprimentos de Dentefrio","Leve 10 Suprimentos de Dentefrio para o Intendente da Horda na Bastilha Lobo do Gelo."},
[5901]={"Praga de cupins!","Use a Jarra de Cupins Vazia nos Cupinzeiros que há nas Terras Pestilentas Orientais. Após conseguir 100 Cupins das Terras Pestilentas, fale novamente com Guel Levine no Baluarte, nas Clareiras de Tirisfal."},
[5902]={"Praga de cupins!","Encontre um lugar apropriado para pôr o Barril de Cupins das Terras Pestilentas no centro da Serraria de Beiranorte, que fica nas Terras Pestilentas Ocidentais."},
[5922]={"Clareira da Lua","Use o feitiço \"Teleporte: Clareira da Lua\" para viajar para a Clareira da Lua. Ao chegar, fale com Dendrite Stellardor, no vilarejo de Refúgio Noturno."},
[5926]={"Atendendo o chamado","Fale com Turak Runa Totem no Platô dos Anciãos, que fica no Penhasco do Trovão."},
[5927]={"Atendendo o chamado","Fale com Turak Runa Totem no Platô dos Anciãos, que fica no Penhasco do Trovão."},
[5928]={"Atendendo o chamado","Fale com Turak Runa Totem no Platô dos Anciãos, que fica no Penhasco do Trovão."},
[5930]={"Espírito do Grande Urso","Procure o Espírito do Grande Urso na região noroeste da Clareira da Lua e aprenda o que ele tem a compartilhar com você sobre a natureza do urso. Quando terminar, fale novamente com Dendrite Stellardor no Refúgio Noturno, que fica na Clareira da Lua."},
[5932]={"De volta ao Penhasco do Trovão","Volte ao Penhasco do Trovão e fale com Turak Runa Totem no Platô dos Anciãos."},
[5941]={"De novo com Crona","Leve a Coleção de Relíquias para Crona em Andorhal."},
[5942]={"Tesouros escondidos","Leve a Chave de Josefo ao Baú de Josefo."},
[5943]={"Caravana Gizelton","Escolte a Caravana Gizelton pelas Ruínas de Mannoroc. Fale com o Smid no Acampamento do Rabiscafuso para receber a recompensa."},
[5944]={"No mundo dos sonhos","Escolte Taelan Fordring para fora de Amparo."},
[5961]={"O campeão da Rainha Banshees","Fale com Nathanos, o Arauto da Praga nas Terras Pestilentas Orientais. Dizem que ele fixou residência no Sítio dos Marris."},
[6002]={"Corpo e coração","Aplique Poeira Lunar Cenariana na Pedra Luniscante entre Mulgore e os Sertões para evocar Lunagarra. Então, enfrente Lunagarra e ganhe a força de corpo e coração que ele possui."},
[6004]={"Negócios inacabados","Mate 2 Socorristas Escarlate, 2 Caçadores Escarlate, 2 Magos Escarlate e 2 Cavaleiros Escarlate antes de voltar a Kirsta Sombrafunda, nas Terras Pestilentas Ocidentais."},
[6021]={"Zaeldarr, o Proscrito","Leve a Cabeça de Zaeldarr ao Zelador Alen na Capela Esperança da Luz."},
[6022]={"Matar com propósito","Vá ao Cruzamento de Corin, a leste, e mate membros do Flagelo que habitam a cidade. Colete 7 pedaços de Putrefação Viva em menos de 10 minutos. Use o Almofariz e Pilão para moer a Putrefação Viva, de maneira a transformá-la em Putrefação Coagulada."},
[6023]={"Negócios inacabados","Mate o Guarda-caça Eiras e o Fidalgo Durgen antes de voltar à Kirsta Sombrafunda, nas Terras Pestilentas Ocidentais."},
[6024]={"A súplica de Hameya","Mate o Infiltrador Hameya. Use a chave dele no Monturo de Terra atrás da Chácara Secreta."},
[6025]={"Negócios inacabados","Entre em Amparo e encontre um lugar alto de onde possa ver a cidade e avaliar as forças da Cruzada Escarlate. Então fale novamente com Kirsta Sombrafunda nas Terras Pestilentas Ocidentais."},
[6026]={"Isso é pedir muito","Leandro Leonardo quer que você pegue 2 Barras de Tório, 1 Bastão Dourado, 8 Bombas de Alto-explosivo e 8 Gatilhos Instáveis."},
[6027]={"O Livro dos Anciãos","Pegue o Livro dos Anciãos e entregue-o para Azore Albamorte na torre de Ethel Rethor."},
[6029]={"O relatório de Visteterna","Entregue o Relatório de Visteterna ao Oficial Argênteo Garush no Baluarte, nas Terras Pestilentas Ocidentais."},
[6030]={"Duque Nicolau Zverenhoff","Entregue o livro \"Estudos sobre Comunicação com Espíritos\" ao Duque Nicolau Zverenhoff na Capela Esperança da Luz, que fica nas Terras Pestilentas Orientais."},
[6031]={"Runatrama","Leve 30 cortes de Runatrama para Meilosh no Domínio dos Presamatos."},
[6032]={"Tecido sagrado","Leve 2 cortes de Lunatrama para Meilosh no Domínio dos Presamatos."},
[6041]={"Quando Leandro canta, eu fico violento","Viaje ao Bosque Pestilento, a noroeste da Esperança da Luz. Destrua 8 Estruturas do Flagelo usando o Composto Químico Especial do Leandro na Marca de Detonação plantada dentro de cada construção. Os Zigurates e Abatedouros foram marcados por instrução de Leandro."},
[6042]={"Pequenos transtornos da Morte-em-Vida","Mate 20 Quirópragos Nóxios e 10 Quirópragos Monstruosos. Fale novamente com Nathanos Arauto da Praga quando você tiver terminado."},
[6061]={"Domando a fera","Use o Bastão de Adestramento para domar um Pinote Adulto. Pratique sua habilidade e depois devolva o Bastão de Adestramento a Yaw Crina Cortante na Aldeia Casco Sangrento."},
[6062]={"Domando a fera","Use o Bastão de Adestramento para domar uma Mosquetusco Hediondo. Pratique sua habilidade e depois devolva o Bastão de Adestramento a Thotar no Monte Navalha."},
[6065]={"O caminho do caçador","Fale com Yaw Crina Cortante na Aldeia Casco Sangrento."},
[6066]={"O caminho do caçador","Fale com Yaw Crina Cortante na Aldeia Casco Sangrento."},
[6067]={"O caminho do caçador","Fale com Yaw Crina Cortante na Aldeia Casco Sangrento."},
