[7181]={"A Lenda de Korrak","De acordo com a lenda, o líder dos poderosos trolls Invernacha aparece esporadicamente para trazer destruição e caos aos moradores do Vale Alterac."},
[7201]={"O último elemento","Vá até o Abismo Rocha Negra e obtenha 10 Essências dos Elementos. Seu primeiro impulso é procurar nos golens e criadores de golens. Você lembra que Vivian Latumba também mencionou elementais."},
[7224]={"Espólios dos inimigos","Leve 20 Sobras de Armadura para o Ferreiro Regzar na Aldeia Lobo do Gelo."},
[7241]={"Em defesa dos Lobo do Gelo","Explore o Vale Alterac, localizado nas Montanhas de Alterac. Encontre o Mestre Guerreiro Laggrond, que fica diante da entrada do túnel, e converse com ele para começar a sua carreira de soldad<o/a> Lobo do Gelo. O Vale Alterac fica ao norte da Serraria Tarren, no sopé das Montanhas de Alterac."},
[7281]={"Amor fraternal","Siga para o território dos Lançatroz e mate o Comandante Carlos Filipe. Em seguida, fale novamente com o Comandante Luis Filipe."},
[7302]={"Senhores do céu caídos","Descubra o que houve com o Comandante de Ala Guze, o Comandante de Ala Jeztor e o Comandante de Ala Mulverick. Fale novamente com o Comandante Mulfort ao completar a missão."},
[7321]={"Caldo reconfortante de tartaruga","Leve 10 pedaços de Carne de Tartaruga e alguns Temperos Reconfortantes para Cristóvão Casaqueiro, na Serraria Tarren."},
[7341]={"Negócio justo"},
[7381]={"O retorno de Korrak","Se Korrak, o Sanguinário, voltar ao Campo de Disputa, procure-o e destrua-o."},
[7385]={"Um galão de sangue"},
[7429]={"Liberdade ainda que tardia"},
[7441]={"Pusillin e o Ancião Azj'Tordin","Vá ao Gládio Cruel e encontre o Diabrete Pusillin. Convença-o usando qualquer meio que for necessário a lhe dar o Livro de Encantamentos de Azj'Tordin."},
[7461]={"A loucura intrínseca","Mate os guardiões que cercam os cinco pilares de força da Prisão de Immol'thar. Quando os pilares se desligarem, o campo de força que cerca Immol'thar se dissipará."},
[7463]={"Bebida arcana","Vá ao Distrito Lenhatorta, no Gládio Cruel, e mate o elemental da água, Rebentágua. Leve a Essência de Rebentágua para o Erudito Lydros, no Ateneu."},
[7481]={"Lendas élficas","Procure Telmius Romanesca no Gládio Cruel. Reporte-se, então, ao Sábio Korolusk na Aldeia Mojache com qualquer informação que você encontrar."},
[7483]={"Incunábulo de Rapidez","Leve 1 Incunábulo de Rapidez, 1 Diamante Preto Límpido, 2 Estilhaços Brilhantes Grandes, e 2 Sangues dos Heróis ao Erudito Lydros no Gládio Cruel para receber um Arcano de Rapidez."},
[7484]={"Incunábulo de Concentração","Leve 1 Incunábulo de Concentração, 1 Diamante Preto Límpido, 4 Estilhaços Brilhantes Grandes, e 2 Peles de Sombra ao Erudito Lydros no Gládio Cruel para receber um Arcano de Concentração."},
[7485]={"Incunábulo de Proteção","Leve 1 Incunábulo de Proteção, 1 Diamante Preto Límpido, 2 Estilhaços Brilhantes Grandes e 1 Sutura de Abominação Puída ao Erudito Lydros no Gládio Cruel para receber um Arcano de Proteção."},
