[7727]={"Incendossauro? É de comer?","Hansel Mão-pesada quer que você mate 20 Incendossauros."},
[7728]={"OBJETOS ROUBADOS: Alcaraviz de Ferraria e Luneta do Espia","Encontre e devolva o Alcaraviz de Ferraria e a Luneta do Espia ao Capataz Scrange na Garganta Abrasadora."},
[7729]={"TEMOS VAGAS: desbancando a concorrência","Mate 15 Capatazes Ferro Negro e 15 Feitores Ferro Negro. Depois, fale novamente com Capataz Scrange, na Garganta Abrasadora."},
