[7840]={"Banha perdeu o almoço","Banha na Aldeia Revatusco, que fica nas Terras Agrestes, quer que você encontre o Almoço do Banha. Fale novamente com ele quando a tarefa for concluída."},
[7841]={"Mensagem para os Martelo Feroz","Joho'sér Mujik'ka da Aldeia Revatusco, que fica nas Terras Agrestes, quer que você mate 15 Vanguardeiros do Altovale, 15 Batedores de Altovale, 15 Atiradores Peritos do Altovale e 15 Patrulheiros do Altovale. Quando terminar, fale novamente com ele."},
[7842]={"Mais uma mensagem para os Martelo Feroz","Joho'sér Mujik'ka da Aldeia Revatusco, que fica nas Terras Agrestes, quer que você leve para ele 10 Penas Longas Elegantes extraídas dos grifos que habitam as Terras Agrestes. Quando terminar, fale novamente com ele."},
[7843]={"A mensagem final para os Martelo Feroz","Joho'sér Mujik'ka da Aldeia Revatusco, que fica nas Terras Agrestes, quer que você viaje para o Ninho da Águia, na região oeste das Terras Agrestes, e deixe a Mensagem Final para os Martelo Feroz ao lado do poço no centro da cidade. Quando terminar, fale novamente com ele."},
[7844]={"Primos canibais","A Mística Yayo'jin da Aldeia Revatusco, que fica nas Terras Agrestes, quer que você mate 30 Escalpeladores Ramatorpe e 15 Adivinhos Ramatorpe. Quando terminar, fale novamente com ela."},
[7845]={"Capturaram o Ancião Presa-arrancada!","Primeva Presa-arrancada, da Aldeia Revatusco nas Terras Agrestes, quer que você resgate o companheiro dela, Ancião Presa-arrancada, que está em Jintha'Alor."},
[7846]={"Pegue a chave!","O Ancião Presa-arrancada, em Jintha'Alor, quer que você mate Hitah'ya, a Guardiã e pegue a Chave dos Grilhões para soltá-lo. Quando tiver a chave, fale novamente com o Ancião Presa-arrancada."},
[7847]={"Uma resposta para Primeva Presa-arrancada","O Ancião Presa-arrancada, em Jintha'Alor, quer que você fale com Primeva Presa-arrancada, na Aldeia Revatusco, e avise que ele foi resgatado."},
[7848]={"Harmonização com o Núcleo","Vá ao portal da entrada do Núcleo Derretido no Abismo Rocha Negra e recupere um Fragmento de Núcleo. Fale novamente com Lothos Fendespéril na Montanha Rocha Negra após recuperar o Fragmento de Núcleo."},
[7849]={"Angústia da separação","O Guarda-caça Markhor da Aldeia Revatusco, que fica nas Terras Agrestes, quer que você encontre os restos mortais do irmão gêmeo dele. Encontre o Crânio do Guarda-caça Malkhor e os Ossos do Guarda-caça Malkhor e leve-os para o Guarda-caça Markhor."},
[7850]={"Recipientes negros","Primeva Presa-arrancada da Aldeia Revatusco, que fica nas Terras Agrestes, quer que você encontre 10 Recipientes com Sangue Maculado em Jintha'Alor. Quando terminar, fale novamente com Primeva Presa-arrancada."},
[7861]={"Procura-se: Sacerdotisa Torpe Bagata e seus lacaios","Você recebeu ordens de matar a Sacerdotisa Torpe Bagata e 20 Guardas Aman'zasi Ramatorpe. Quando terminar, procure Primeva Presa-arrancada, na Aldeia Revatusco, que fica nas Terras Agrestes."},
[7862]={"Temos vagas: Capitão da Guarda da Aldeia Revatusco","Você recebeu a missão de dizimar 20 Berserkers Ramatorpe, 20 Caçadores Sombrios Ramatorpe, 20 Bebe-sangue Ramatorpe e 20 Devoradores de Almas Ramatorpe."},
