[8805]={"Botas para a guarda","Leve 3 Botas Ornadas de Mithril para Vish Kozus, Capitão da Guarda, no Forte Cenariano, em Silithus. Você também precisa entregar as Instruções de Logística II para concluir a missão."},
[8806]={"Pedras de amolar para a guarda","Leve 10 Pedras de Amolar Densas, 10 Pedras de Amolar Maciças e 10 Pedras de Amolar Pesadas para Vish Kozus, Capitão da Guarda, no Forte Cenariano, em Silithus. Você também precisa entregar as Instruções de Logística III para concluir a missão."},
[8807]={"Matérias-primas de vidência","Leve 1 Estilhaço Brilhante Grande, 1 Estilhaço Radiante Grande e 1 Esmeralda Enorme para a Geóloga Matarriso, no Forte Cenariano, em Silithus. Você também precisa entregar as Instruções de Logística V para concluir esta missão."},
[8808]={"Suprimentos de uniformização","Leve 1 Lunatrama, 2 Peças de Runatrama e 1 Seda de Aranha Ferroteia para o Arauto do Vento Chifre Altivo no Forte Cenariano, em Silithus. Você também precisa entregar as Instruções de Logística VIII para cumprir esta missão."},
[8809]={"Materiais extraordinários e onde se encontram","Leve 2 Barras de Tório Encantado e 2 Couros Encantados para Vargus, no Forte Cenariano, em Silithus. Você também precisa entregar as Instruções de Logística IX para concluir a missão."},
[8810]={"Bandagens para o campo","Leve 30 Bandagens Grossas de Runatrama, 30 Bandagens Grossas de Seda e 30 Bandagens Grossas de Magitrama para o Arauto do Vento Chifre Altivo, no Forte Cenariano, em Silithus. Você também precisa entregar as Instruções de Logística X para concluir esta missão."},
