[8994]={"Preparativos finais","Colete 40 Braceletes de Rocha Negra e consiga um Frasco de Poder Supremo. Leve tudo para Bodley, dentro da Montanha Rocha Negra."},
[8995]={"Mea culpa, Lorde Valthalak","Use o Braseiro de Sinalização para evocar o Lorde Valthalak. Acabe com ele e use o Amuleto do Lorde Valthalak no cadáver. Em seguida, devolva o Amuleto do Lorde Valthalak ao Espírito de Lorde Valthalak."},
[8996]={"Fale novamente com Bodley","Fale novamente com Bodley na Montanha Rocha Negra e dê a ele o Braseiro de Sinalização."},
[8998]={"De volta ao começo","Fale com Mokvar no Castelo Grommash, que fica no Vale da Sabedoria, em Orgrimmar."},
[9007]={"Deixando o melhor para o final","Entregue seu Capucho do Coração Selvagem e seu Colete do Coração Selvagem a Mokvar."},
[9008]={"Deixando o melhor para o final","Entregue seu Casquete do Espreitador de Feras e sua Túnica do Espreitador de Feras a Mokvar."},
