[9011]={"Deixando o melhor para o final","Dê a Mokvar sua Coifa dos Elementos e seu Colete dos Elementos."},
[9012]={"Deixando o melhor para o final","Entregue sua Máscara de Brumedo e sua Veste de Brumedo a Mokvar."},
[9013]={"Deixando o melhor para o final","Entregue seu Elmo do Valor e seu Peitoral do Valor a Mokvar."},
[9014]={"Deixando o melhor para o final","Entregue sua Coroa do Magíster e suas Vestes do Magíster a Mokvar."},
[9015]={"O desafio","Viaje até o Círculo da Lei no Abismo Rocha Negra e coloque o Estandarte da Provocação no centro enquanto ouve a sentença do Supremo Juiz Durólito. Mate Theldren e seus gladiadores e fale novamente com Anthion Harmon nas Terras Pestilentas Orientais em posse da primeira parte do amuleto de Lorde Valthalak."},
