[98545]={"A carta de Leonid","Entregue a Carta Selada para Glix Xizzix na Cidade Baixa."},
[98601]={"Um caminho árduo","Leia o Pergaminho Consagrado e fale com Aramis Cerramartelo na igreja de Plangemortis."},
[98738]={"Bênçãos do Grande Espírito Felino Pairavento","Procure o Espírito do Grande Urso na região noroeste da Clareira da Lua e aprenda o que ele tem a compartilhar com você sobre a natureza do urso. Quando terminar, fale novamente com Dendrite Stellardor no Refúgio Noturno, que fica na Clareira da Lua."},
[98739]={"Bênçãos do Espírito do Grande Felino","Fale com Dendrite."},
[98823]={"Eco telúrico","Leve a Relíquia Titânica para Muln Terrafúria no Platô do Vigia dos Céus, no noroeste de Mulgore."},
[99048]={"A mão desaparecida","Encontre Heglan Sombrolho ao norte da Bastilha Tiragarde."},
[99049]={"Ameaça vinda de baixo","Encontre sinais do que atacou Heglan Sombrolho."},
[99051]={"Ameaça vinda de baixo","Colete 9 Espinhapinas de Naga."},
[99052]={"Ameaça vinda de baixo","Mate o Gigante do Mar na costa norte de Durotar e traga uma prova do seu feito."},
[99079]={"Passo-longo Malah","Encontre a Passo-longo Malah Vento Longo a leste da Aldeia Casco Sangrento, perto da divisa de Mulgore."},
[99080]={"Expulse todos","Mate 6 Centauros Galath e 4 Vanguardeiros Galath e leve a cabeça de Herak, o Pilhador, até Baine Casco Sangrento."},
[99081]={"Augúrios sinistros","Leve o Relatório da Passo-longo Malah ao Valente Trilha Selvagem na Aldeia Casco Sangrento."},
[99082]={"O Grande Chefe","Peça uma audiência com o Grande Chefe Caerne Casco Sangrento no Penhasco do Trovão."},
[99101]={"Nosso inimigo ancestral","Leve o Relatório da Passo-longo Malah a Baine Casco Sangrento."},
[99108]={"Treino de pugilato","Derrote outros 3 jogadores em duelos ou Guerreiros Novatos para Tang Casco de Pedra."},
[99123]={"Perdida nas sombras","Ajude Pal'juh a escapar do Penedo de Kolkar e avise o Mestre Vornal na Aldeia Sen'jin quando conseguir."},
[99134]={"Disciplina","Puna 5 Necroguardas para o Executor Zigano."},
[99141]={"Paciência","Obtenha os relatórios do Necroguarda Dinis, do Necroguarda Kristof e de Gordo para o Executor Zigano."},
[99142]={"Erva de Tumba","Colete 5 Ervas de Tumba e entregue para o Boticário-júnior Hollanda."},
[99144]={"Em busca de refúgio","Ajude Barreto Aurolita a fugir da Guarita do Cruzado e informe Shária Calmafonte, em Montalvo, de que ele está a salvo."},
[99152]={"Assim na terra como no céu","Colete 6 Ossos Levemente Brilhantes para Hilda, a Devastadora."},
[99153]={"E o sectário levou","Encontre o Fragmento de Cristal Oculto abaixo do Vale das Sombras para Efraim Barbaro."},
[99156]={"Patrulha da retaguarda","Leve o Coração de Talharretalha até a Necroguarda Lina."},
[99196]={"Doação de lã"},
[99411]={"Kyle sumiu!","Ahab Casco Trigo, na Aldeia Casco Sangrento em Mulgore, quer que você alimente o bichinho de estimação dele, Kyle, o Frenético."},
}
